<?php
namespace App\Console\Commands;use App\Services\ExcelImportService;use Illuminate\Console\Command;class ImportEmployeeExcel extends Command{protected $signature='import:employee-excel {--advance=} {--timesheet=} {--project=WADI SAFAR} {--month=2} {--year=2026}';protected $description='Import employees, attendance, advances and extra duty from Excel';public function handle(ExcelImportService $s){$a=$this->option('advance')?:storage_path('app/imports/reference/Advance Sheet 2025 for Weekly 2.xlsx');$t=$this->option('timesheet')?:storage_path('app/imports/reference/02,FEBRUARY 2026- TIMESHEET  WADI SAFAR PROJECT - .xlsx');$sum=$s->import(file_exists($a)?$a:null,file_exists($t)?$t:null,$this->option('project'),(int)$this->option('month'),(int)$this->option('year'));$this->info(json_encode($sum,JSON_PRETTY_PRINT));return self::SUCCESS;}}
